import React, { useEffect, useMemo, useState } from "react";
import { id as hashId, parseUnits } from "ethers";
import { call, createAgreement as createOnChainAgreement, factoryArbitrationAddress, type AgreementRecord } from "./contract";
import { acceptCommercialInvitation, acceptCommercialProposal, confirmCommercialDeployment, createCommercialDeployIntent, createCommercialAgreement, createCommercialInvitation, getCommercialAgreement, getCommercialDiff, getMyProfile, getPublicInvitation, listCommercialProposals, lookupCommercialProfile, saveMyProfile, searchCommercialProfiles, sendCommercialProposal, type CommercialAgreement, type CommercialDiff, type CommercialMilestone, type CommercialProfile, type CommercialProposal } from "./commercialApi";
import { DELIVERY_TERMS, MILESTONE_SUGGESTIONS, suggestionsForTerm, termsForMode, type TransportMode } from "../../shared/terms";
import type { EmbeddedWalletSession } from "./wallet";

type Role = "BUYER" | "SELLER";
type Screen = "profile" | "role" | "goods" | "transport" | "terms" | "financial" | "parties" | "review" | "invite" | "builder" | "proposal" | "counter" | "diff" | "mutual";
type ResolutionPolicy = "ARCTRADE_DEFAULT" | "MUTUAL_RESOLVER";
type CounterpartyMode = "search" | "invite" | "address";
type Draft = { category: string; description: string; quantity: string; quantityUnit: string; qualityStandard: string; mode: TransportMode | ""; originCountry: string; originPortCity: string; destinationCountry: string; destinationPortCity: string; freightArranger: string; insuranceArranger: string; incoterm: string; deliveryNamedPlace: string; totalUSDC: string; deliveryDeadline: string; negotiationExpiry: string; commitmentWindowSec: string; arbitrationTimeoutSec: string; counterparty: string; counterpartyMode: CounterpartyMode; counterpartyProfile: CommercialProfile | null; resolutionPolicy: ResolutionPolicy; resolverAddress: string };
type MilestoneDraft = CommercialMilestone & { reference: string };

const initialDraft: Draft = { category: "", description: "", quantity: "", quantityUnit: "units", qualityStandard: "", mode: "", originCountry: "", originPortCity: "", destinationCountry: "", destinationPortCity: "", freightArranger: "", insuranceArranger: "", incoterm: "", deliveryNamedPlace: "", totalUSDC: "", deliveryDeadline: futureDate(30), negotiationExpiry: futureDate(7), commitmentWindowSec: "172800", arbitrationTimeoutSec: "172800", counterparty: "", counterpartyMode: "search", counterpartyProfile: null, resolutionPolicy: "ARCTRADE_DEFAULT", resolverAddress: "" };
const operatorAddress = (import.meta.env.VITE_OPERATOR_ADDRESS || "0x0bF9683D68c79976281A6a16CFb9A49608a1a37c").trim();
const categories = ["Physical goods", "Agricultural produce", "Raw materials", "Industrial equipment", "Textiles", "Electronics", "Chemicals", "Other"];
const modes: Array<{ value: TransportMode; label: string; icon: string }> = [{ value: "sea", label: "Sea", icon: "≈" }, { value: "air", label: "Air", icon: "✦" }, { value: "road", label: "Road", icon: "▰" }, { value: "rail", label: "Rail", icon: "═" }, { value: "inland_waterway", label: "Inland waterway", icon: "⌁" }, { value: "multimodal", label: "Multimodal", icon: "＋" }];
const fieldName: Record<string, string> = { description: "Description", basisPoints: "Payment share", sellerDeadlineSec: "Seller submission deadline", buyerResponseWindowSec: "Buyer review window", disputeWindowSec: "Dispute window", proofDescription: "Proof description" };

function futureDate(days: number) { const date = new Date(Date.now() + days * 86400000); date.setMinutes(date.getMinutes() - date.getTimezoneOffset()); return date.toISOString().slice(0, 16); }
function amount(total: string, basisPoints: number) { const value = Number(total || 0) * basisPoints / 10000; return `$${value.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`; }
function moneyFromBasis(total: string, basisPoints: number) { return amount(total, basisPoints); }
function toMilestones(term: string): MilestoneDraft[] { return (suggestionsForTerm(term) as CommercialMilestone[]).map((item, index) => ({ ...item, index, reference: index === 0 ? "agreement" : `M${index - 1}` })); }
function defaultMilestones(): MilestoneDraft[] { return [{ description: "Delivery confirmed", basisPoints: 10000, sellerDeadlineSec: 7 * 86400, buyerResponseWindowSec: 48 * 3600, disputeWindowSec: 48 * 3600, proofDescription: "Signed delivery receipt", reference: "agreement" }]; }

export function InviteLanding({ token, session, onSignIn, onAccepted, onHome }: { token: string; session: EmbeddedWalletSession | null; onSignIn: () => void; onAccepted: (agreementId: string) => void; onHome: () => void }) {
  const [invitation, setInvitation] = useState<import("./commercialApi").PublicInvitation | null>(null);
  const [profile, setProfile] = useState<CommercialProfile | null>(null);
  const [companyName, setCompanyName] = useState("");
  const [country, setCountry] = useState("");
  const [tradeCategory, setTradeCategory] = useState("");
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  useEffect(() => { let active = true; getPublicInvitation(token).then(value => { if (active) setInvitation(value); }).catch(error => { if (active) setMessage(error instanceof Error ? error.message : "This invitation is unavailable."); }); if (session) getMyProfile(session).then(value => { if (!active) return; setProfile(value); if (value) { setCompanyName(value.companyName); setCountry(value.country); setTradeCategory(value.tradeCategory || ""); } }).catch(error => { if (active) setMessage(error instanceof Error ? error.message : "Could not load your profile."); }); return () => { active = false; }; }, [session, token]);
  const accept = async () => { if (!session) return onSignIn(); setBusy(true); setMessage(""); try { let currentProfile = profile; if (!currentProfile) { currentProfile = await saveMyProfile(session, { companyName, country, tradeCategory: tradeCategory || null }); setProfile(currentProfile); } const result = await acceptCommercialInvitation(session, token); localStorage.removeItem("arc-trade-pending-invite"); onAccepted(result.agreementId); } catch (error) { setMessage(error instanceof Error ? error.message : "Could not accept this invitation."); } finally { setBusy(false); } };
  return <main className="commercial-shell"><header className="commercial-header"><a className="commercial-brand" href="/#resources" aria-label="Arc Trade home" onClick={event => { event.preventDefault(); onHome(); }}><span className="mark">AT</span><span>Arc<span>Trade</span></span></a><button className="commercial-signout" onClick={onHome}>Back to Arc Trade</button></header>{message && <div className="commercial-message" role="status">{message}</div>}{!invitation && !message && <Frame step="INVITATION" title="Loading invitation" sub="Checking the agreement link…" />}{invitation && <Frame step="INVITATION / COUNTERPARTY ONBOARDING" title="You have been invited to a trade agreement" sub={`From ${invitation.buyerCompanyName}. This link expires ${new Date(invitation.expiresAt).toLocaleString()}.`}><div className="trade-strip"><strong>{invitation.goodsDescription}</strong><span>{invitation.originCountry} → {invitation.destinationCountry} · ${Number(invitation.totalUSDC).toLocaleString()} USDC</span></div>{session && !profile && <><label className="form-label">Company name <span>required</span><input value={companyName} onChange={event => setCompanyName(event.target.value)} placeholder="Your registered company name" /></label><label className="form-label">Country <span>required</span><input value={country} onChange={event => setCountry(event.target.value)} placeholder="Country of registration" /></label><label className="form-label">Trade category <span>optional</span><select value={tradeCategory} onChange={event => setTradeCategory(event.target.value)}><option value="">Select a category</option>{categories.map(category => <option key={category}>{category}</option>)}</select></label></>}{session && profile && <p className="identity-note">Accepting as <strong>{profile.companyName}</strong> · {profile.country}</p>}<button onClick={() => void accept()} disabled={busy || Boolean(session && !profile && (!companyName.trim() || !country))}>{busy ? "Joining agreement…" : session ? "Accept invitation →" : "Review and create access →"}</button></Frame>}</main>;
}

export function CommercialWorkflow({ session, onSignOut, onHome, profileName = "", initialAgreementId = "" }: { session: EmbeddedWalletSession; onSignOut: () => void; onHome: () => void; profileName?: string; initialAgreementId?: string }) {
  const [screen, setScreen] = useState<Screen>("profile");
  const [role, setRole] = useState<Role | null>(null);
  const [draft, setDraft] = useState<Draft>(initialDraft);
  const [agreement, setAgreement] = useState<CommercialAgreement | null>(null);
  const [proposal, setProposal] = useState<CommercialProposal | null>(null);
  const [milestones, setMilestones] = useState<MilestoneDraft[]>([]);
  const [editing, setEditing] = useState<number | null>(null);
  const [note, setNote] = useState("");
  const [diff, setDiff] = useState<CommercialDiff | null>(null);
  const [busy, setBusy] = useState("");
  const [message, setMessage] = useState("");
  const [loadId, setLoadId] = useState("");
  const [profile, setProfile] = useState<CommercialProfile | null>(null);
  const [profileReady, setProfileReady] = useState(false);
  const [inviteUrl, setInviteUrl] = useState("");
  const [inviteExpiresAt, setInviteExpiresAt] = useState("");

  const update = <K extends keyof Draft>(key: K, value: Draft[K]) => setDraft(current => ({ ...current, [key]: value }));
  const totalBasis = milestones.reduce((sum, milestone) => sum + milestone.basisPoints, 0);
  const actorIsBuyer = role === "BUYER";
  const canSend = totalBasis === 10000 && milestones.length > 0 && milestones.every(item => item.description.trim() && item.proofDescription.trim() && item.sellerDeadlineSec > 0 && item.buyerResponseWindowSec > 0 && item.disputeWindowSec > 0);
  const validTerms = useMemo(() => draft.mode ? termsForMode(draft.mode) : [], [draft.mode]);

  useEffect(() => {
    let active = true;
    getMyProfile(session).then(value => { if (!active) return; setProfile(value); setProfileReady(true); setScreen(value ? "role" : "profile"); }).catch(error => { if (active) setMessage(error instanceof Error ? error.message : "Could not load your company profile."); });
    return () => { active = false; };
  }, [session]);

  const completeProfile = async (input: { companyName: string; country: string; tradeCategory?: string | null }) => { setBusy("profile"); setMessage(""); try { const saved = await saveMyProfile(session, input); setProfile(saved); setProfileReady(true); setScreen("role"); } catch (error) { setMessage(error instanceof Error ? error.message : "Could not save your company profile."); } finally { setBusy(""); } };

  const beginRole = (next: Role) => { setRole(next); setScreen("goods"); };
  const continueGoods = () => { if (!draft.description.trim()) { setMessage("Describe the goods before continuing."); return; } setMessage(""); setScreen("transport"); };
  const continueTransport = () => { if (!draft.mode || !draft.originCountry || !draft.originPortCity.trim() || !draft.destinationCountry || !draft.destinationPortCity.trim() || !draft.freightArranger || !draft.insuranceArranger) { setMessage("Complete the transport and route details before continuing."); return; } setMessage(""); setScreen("terms"); };
  const continueTerms = () => { if (!draft.incoterm) { setMessage("Choose delivery terms, or select Other / not yet agreed."); return; } if (draft.incoterm !== "OTHER" && !draft.deliveryNamedPlace.trim()) { setMessage("Add the named place for the selected delivery terms."); return; } setMilestones(draft.incoterm === "OTHER" ? defaultMilestones() : toMilestones(draft.incoterm)); setMessage(""); setScreen("financial"); };
  const continueFinancial = () => { if (!draft.totalUSDC || Number(draft.totalUSDC) <= 0) { setMessage("You must agree a trade value before the agreement can be created."); return; } const delivery = new Date(draft.deliveryDeadline); const expiry = new Date(draft.negotiationExpiry); if (!draft.deliveryDeadline || Number.isNaN(delivery.valueOf()) || delivery <= new Date() || !draft.negotiationExpiry || Number.isNaN(expiry.valueOf()) || expiry <= new Date() || expiry >= delivery) { setMessage("Set a future agreement deadline before the delivery deadline."); return; } setMessage(""); setScreen("parties"); };
  const continueParties = () => { const counterpartyValid = draft.counterpartyMode === "invite" || /^0x[0-9a-fA-F]{40}$/.test(draft.counterparty); const resolverValid = !draft.resolverAddress || /^0x[0-9a-fA-F]{40}$/.test(draft.resolverAddress); if (!counterpartyValid || !resolverValid || !operatorAddress) { setMessage("Choose a counterparty path and complete the required account details. The platform operator must be configured."); return; } const buyer = actorIsBuyer ? session.address : draft.counterparty; const seller = actorIsBuyer ? draft.counterparty : session.address; if (draft.counterparty && draft.counterparty.toLowerCase() === session.address.toLowerCase()) { setMessage("The counterparty account must be different from yours."); return; } if (draft.resolverAddress && [buyer, seller].filter(Boolean).some(address => address.toLowerCase() === draft.resolverAddress.toLowerCase())) { setMessage("The nominated resolver must be independent of the buyer and seller."); return; } setMessage(""); setScreen("review"); };
  const create = async () => { setBusy("create"); setMessage(""); try { const body = { buyerAddress: actorIsBuyer ? session.address : (draft.counterparty || null), sellerAddress: actorIsBuyer ? (draft.counterparty || null) : session.address, resolutionPolicy: draft.resolutionPolicy, assignedResolverAddress: draft.resolverAddress || null, operatorAddress, totalUSDC: draft.totalUSDC, negotiationExpiry: new Date(draft.negotiationExpiry).toISOString(), commitmentWindowSec: Number(draft.commitmentWindowSec), arbitrationTimeoutSec: Number(draft.arbitrationTimeoutSec), goodsDescription: draft.description, goodsCategory: draft.category || null, quantity: draft.quantity || null, quantityUnit: draft.quantity ? draft.quantityUnit : null, qualityStandard: draft.qualityStandard || null, transportMode: draft.mode, originCountry: draft.originCountry, originPortCity: draft.originPortCity, destinationCountry: draft.destinationCountry, destinationPortCity: draft.destinationPortCity, incoterm: draft.incoterm, deliveryNamedPlace: draft.deliveryNamedPlace || null, freightArranger: draft.freightArranger, insuranceArranger: draft.insuranceArranger, deliveryDeadline: new Date(draft.deliveryDeadline).toISOString() }; const result = await createCommercialAgreement(session, body); setAgreement(result.agreement); if (draft.counterpartyMode === "invite") { const invitation = await createCommercialInvitation(session, result.agreement.id); setInviteUrl(invitation.inviteUrl); setInviteExpiresAt(invitation.expiresAt); setScreen("invite"); setMessage("Your draft is ready. Send the invitation link to your counterparty."); } else { setScreen("builder"); setMessage(`Agreement ${result.referenceCode} is ready for milestone negotiation.`); } } catch (error) { setMessage(error instanceof Error ? error.message : "Could not create the agreement."); } finally { setBusy(""); } };
  const send = async () => { if (!agreement || !canSend) return; setBusy("send"); setMessage(""); try { const created = await sendCommercialProposal(session, agreement.id, milestones.map(({ reference: _reference, ...item }) => item), note); setProposal(created); setAgreement(current => current ? { ...current, latestProposal: created, status: "negotiating" } : current); setScreen("proposal"); setNote(""); } catch (error) { setMessage(error instanceof Error ? error.message : "Could not send the proposal."); } finally { setBusy(""); } };
  const accept = async () => { if (!agreement || !proposal) return; setBusy("accept"); setMessage(""); try { const result = await acceptCommercialProposal(session, agreement.id, proposal.id); setProposal(result.proposal); if (result.agreed) { setAgreement(current => current ? { ...current, status: "agreed", agreedMilestones: result.agreedMilestones } : current); setMilestones((result.agreedMilestones || []).map((item, index) => ({ ...item, index, reference: index === 0 ? "agreement" : `M${index - 1}` }))); setScreen("mutual"); } else setMessage("Your acceptance is recorded. The other party still needs to accept these terms."); } catch (error) { setMessage(error instanceof Error ? error.message : "Could not record acceptance."); } finally { setBusy(""); } };
  const suggestChanges = async () => { if (!agreement?.latestProposal) return; setBusy("diff"); try { const nextDiff = await getCommercialDiff(session, agreement.id, agreement.latestProposal.id); setDiff(nextDiff); setMilestones(agreement.latestProposal.milestones.map((item, index) => ({ ...item, index, reference: index === 0 ? "agreement" : `M${index - 1}` }))); setScreen("counter"); } catch (error) { setMessage(error instanceof Error ? error.message : "Could not open the counter-proposal."); } finally { setBusy(""); } };
  const openDiff = async () => { if (!agreement || !proposal) return; try { setDiff(await getCommercialDiff(session, agreement.id, proposal.id)); setScreen("diff"); } catch (error) { setMessage(error instanceof Error ? error.message : "Could not load the changes."); } };
  const saveDraft = () => { if (agreement) localStorage.setItem(`arc-trade-commercial-draft:${agreement.id}`, JSON.stringify(milestones)); setMessage("Milestone draft saved on this device. It has not been sent."); };
  const deploy = async () => { if (!agreement) return; setBusy("deploy"); setMessage(""); try { const latest = await getCommercialAgreement(session, agreement.id); const agreedMilestones = latest.agreedMilestones; if (latest.status !== "agreed" || !agreedMilestones?.length) throw new Error("The agreement is not ready for deployment"); const intent = await createCommercialDeployIntent(session, agreement.id); const factoryAuthority = await factoryArbitrationAddress(session.signer); if (factoryAuthority.toLowerCase() !== intent.arbitrationAddress.toLowerCase()) throw new Error("The configured factory is not bound to the Resolution Router. Deployment was stopped before contract creation."); const onChain: AgreementRecord = await createOnChainAgreement(session.signer, hashId(`arc-trade-commercial:${agreement.id}`), intent.sellerAddress, parseUnits(intent.totalUSDC, 6), BigInt(intent.negotiationExpiry), BigInt(intent.commitmentWindow), BigInt(intent.arbitrationTimeout)); if (!onChain.txHash) throw new Error("Deployment transaction hash unavailable"); const verified = await confirmCommercialDeployment(session, agreement.id, onChain.txHash); const tx = await call(session.signer, verified.contractAddress!, "proposeMilestones", [agreedMilestones.map(item => ({ description: item.description, basisPoints: item.basisPoints, sellerDeadline: item.sellerDeadlineSec, buyerResponseWindow: item.buyerResponseWindowSec, disputeWindow: item.disputeWindowSec }))]); const receipt = await tx.wait(); setAgreement(current => current ? { ...current, contractAddress: verified.contractAddress, status: "deployed", deploymentBlock: Number(receipt?.blockNumber || verified.deploymentBlock), agreedMilestones } : current); setMessage("The agreement is deployed once. The existing milestone runner can now load its settlement record."); } catch (error) { setMessage(error instanceof Error ? error.message : "Deployment did not complete. No registry address was recorded."); } finally { setBusy(""); } };
  const load = async (requestedId = loadId) => { if (!requestedId.trim()) return; setBusy("load"); setMessage(""); try { const loaded = await getCommercialAgreement(session, requestedId.trim()); const loadedRole: Role | null = String(loaded.buyerAddress || "").toLowerCase() === session.address.toLowerCase() ? "BUYER" : String(loaded.sellerAddress || "").toLowerCase() === session.address.toLowerCase() ? "SELLER" : null; if (!loadedRole) throw new Error("This account is not a buyer or seller on that agreement"); setRole(loadedRole); setAgreement(loaded); setDraft(fromAgreement(loaded)); const proposals = await listCommercialProposals(session, loaded.id); const latest = proposals.at(-1) || loaded.latestProposal; setProposal(latest); if (loaded.status === "agreed" || loaded.status === "deployed") { setMilestones((loaded.agreedMilestones || latest?.milestones || []).map((item, index) => ({ ...item, index, reference: index === 0 ? "agreement" : `M${index - 1}` }))); setScreen("mutual"); } else if (latest && latest.proposedBy.toLowerCase() !== session.address.toLowerCase()) { if (latest.arrayVersion > 1) { setDiff(await getCommercialDiff(session, loaded.id, latest.id)); setScreen("diff"); } else setScreen("proposal"); } else { setMilestones((latest?.milestones || defaultMilestones()).map((item, index) => ({ ...item, index, reference: index === 0 ? "agreement" : `M${index - 1}` }))); setScreen("builder"); } } catch (error) { setMessage(error instanceof Error ? error.message : "Could not load that agreement."); } finally { setBusy(""); } };
  useEffect(() => { if (profileReady && initialAgreementId) { setLoadId(initialAgreementId); void load(initialAgreementId); } }, [profileReady, initialAgreementId]);

  const goBack = (next: Screen) => { setMessage(""); setScreen(next); };
  return <main className="commercial-shell"><header className="commercial-header"><a className="commercial-brand" href="/#resources" aria-label="Arc Trade home" onClick={event => { event.preventDefault(); onHome(); }}><span className="mark">AT</span><span>Arc<span>Trade</span></span></a><span className="commercial-context"><a href="/#resources" onClick={event => { event.preventDefault(); onHome(); }}>Trade desk</a><span aria-hidden="true">/</span><strong>{agreement ? agreement.referenceCode : "Draft a proposal"}</strong></span><button className="commercial-signout" onClick={onSignOut}>Sign out</button></header>{message && <div className="commercial-message" role="status">{message}</div>}{!profileReady && <Frame step="PROFILE" title="Preparing your commercial profile" sub="Checking your company identity…" />}{profileReady && screen === "profile" && <ProfileScreen initialName={profileName} busy={busy} onSave={input => void completeProfile(input)} />}{profileReady && screen === "role" && <RoleScreen onSelect={beginRole} loadId={loadId} setLoadId={setLoadId} onLoad={() => void load()} busy={busy} />}{screen === "goods" && <GoodsScreen draft={draft} update={update} onNext={continueGoods} />}{screen === "transport" && <TransportScreen draft={draft} update={update} onNext={continueTransport} onBack={() => goBack("goods")} />}{screen === "terms" && <TermsScreen mode={draft.mode as TransportMode} selected={draft.incoterm} namedPlace={draft.deliveryNamedPlace} onSelect={value => update("incoterm", value)} onNamedPlace={value => update("deliveryNamedPlace", value)} terms={validTerms} onNext={continueTerms} onBack={() => goBack("transport")} />}{screen === "financial" && <FinancialScreen draft={draft} update={update} onNext={continueFinancial} onBack={() => goBack("terms")} />}{screen === "parties" && <PartiesScreen draft={draft} update={update} session={session} onNext={continueParties} onBack={() => goBack("financial")} />}{screen === "review" && <ReviewScreen draft={draft} role={role!} session={session} onCreate={() => void create()} onBack={() => goBack("parties")} busy={busy} />}{screen === "invite" && agreement && <InviteWaitScreen agreement={agreement} inviteUrl={inviteUrl} expiresAt={inviteExpiresAt} session={session} onContinue={() => { setScreen("builder"); setMessage("Your counterparty has joined. Build the opening milestone proposal."); }} />}{screen === "builder" && <BuilderScreen total={draft.totalUSDC} milestones={milestones} setMilestones={setMilestones} editing={editing} setEditing={setEditing} note={note} setNote={setNote} canSend={canSend} onSave={saveDraft} onSend={() => void send()} busy={busy} />}{screen === "proposal" && agreement && proposal && <ProposalScreen agreement={agreement} proposal={proposal} role={role!} onAccept={() => void accept()} onChanges={() => void suggestChanges()} busy={busy} />}{screen === "counter" && <BuilderScreen total={draft.totalUSDC} milestones={milestones} setMilestones={setMilestones} editing={editing} setEditing={setEditing} note={note} setNote={setNote} diff={diff} canSend={canSend} onSave={saveDraft} onSend={() => void send()} busy={busy} counter />}{screen === "diff" && agreement && proposal && diff && <DiffScreen total={agreement.totalUSDC} diff={diff} onAccept={() => void accept()} onCounter={() => setScreen("counter")} onReject={() => { setScreen("proposal"); setMessage("The current proposal remains open. You can propose different terms when ready."); }} busy={busy} />}{screen === "mutual" && agreement && <MutualScreen agreement={agreement} milestones={milestones} role={role!} onDeploy={() => void deploy()} busy={busy} />}</main>;
}

function fromAgreement(agreement: CommercialAgreement): Draft { const counterparty = agreement.buyerAddress || agreement.sellerAddress || ""; return { category: agreement.goodsCategory || "", description: agreement.goodsDescription, quantity: agreement.quantity || "", quantityUnit: agreement.quantityUnit || "units", qualityStandard: agreement.qualityStandard || "", mode: agreement.transportMode as TransportMode, originCountry: agreement.originCountry, originPortCity: agreement.originPortCity, destinationCountry: agreement.destinationCountry, destinationPortCity: agreement.destinationPortCity, freightArranger: agreement.freightArranger, insuranceArranger: agreement.insuranceArranger, incoterm: agreement.incoterm || "OTHER", deliveryNamedPlace: agreement.deliveryNamedPlace || "", totalUSDC: agreement.totalUSDC, deliveryDeadline: localInput(agreement.deliveryDeadline), negotiationExpiry: localInput(agreement.negotiationExpiry), commitmentWindowSec: String(agreement.commitmentWindowSec), arbitrationTimeoutSec: String(agreement.arbitrationTimeoutSec), counterparty, counterpartyMode: "address", counterpartyProfile: null, resolutionPolicy: agreement.resolutionPolicy || "ARCTRADE_DEFAULT", resolverAddress: agreement.assignedResolverAddress || "" }; }
function localInput(value: string) { const date = new Date(value); date.setMinutes(date.getMinutes() - date.getTimezoneOffset()); return date.toISOString().slice(0, 16); }

function Frame({ step, title, sub, children, onBack, next, nextLabel = "Continue", disabled = false }: { step?: string; title: string; sub?: string; children?: React.ReactNode; onBack?: () => void; next?: () => void; nextLabel?: string; disabled?: boolean }) { return <section className="commercial-frame"><div className="commercial-step">{step}</div><h1>{title}</h1>{sub && <p className="commercial-sub">{sub}</p>}{children && <div className="commercial-content">{children}</div>}{next && <div className="commercial-actions">{onBack && <button className="text-button" onClick={onBack}>Back</button>}<button onClick={next} disabled={disabled}>{nextLabel}</button></div>}</section>; }
function ProfileScreen({ initialName, busy, onSave }: { initialName: string; busy: string; onSave: (input: { companyName: string; country: string; tradeCategory?: string | null }) => void }) { const [companyName, setCompanyName] = useState(initialName); const [country, setCountry] = useState(""); const [tradeCategory, setTradeCategory] = useState(""); return <Frame step="PROFILE / COMPANY IDENTITY" title="Complete your company profile" sub="This creates the verified commercial identity used when counterparties search for you." next={() => { if (!companyName.trim() || !country) return; onSave({ companyName: companyName.trim(), country, tradeCategory: tradeCategory || null }); }} nextLabel={busy === "profile" ? "Saving…" : "Continue"} disabled={busy === "profile" || !companyName.trim() || !country}><label className="form-label">Company name <span>required</span><input value={companyName} onChange={event => setCompanyName(event.target.value)} placeholder="e.g. Northstar Logistics" /></label><label className="form-label">Country <span>required</span><input value={country} onChange={event => setCountry(event.target.value)} placeholder="Country of registration" /></label><label className="form-label">Trade category <span>optional</span><select value={tradeCategory} onChange={event => setTradeCategory(event.target.value)}><option value="">Select a category</option>{categories.map(category => <option key={category}>{category}</option>)}</select></label><p className="identity-note">Your wallet remains the unique account identifier. Company details are searchable; they do not authorize settlement or change contract parties.</p></Frame>; }
function RoleScreen({ onSelect, loadId, setLoadId, onLoad, busy }: { onSelect: (role: Role) => void; loadId: string; setLoadId: (value: string) => void; onLoad: () => void; busy: string }) { const [loading, setLoading] = useState(false); return <section className="role-screen"><div className="commercial-step">STEP 01 / YOUR ROLE</div><h1>Start a commercial agreement.</h1><p className="commercial-sub">Choose how you will participate. This role is locked for this agreement.</p><div className="role-options"><button onClick={() => onSelect("BUYER")}><strong>BUYER</strong><span>You are securing goods and approving the payment schedule.</span></button><button onClick={() => onSelect("SELLER")}><strong>SELLER</strong><span>You are supplying goods and submitting proof at each milestone.</span></button></div><div className="load-existing"><button className="text-button" onClick={() => setLoading(value => !value)}>Load existing agreement</button>{loading && <div className="load-row"><input placeholder="Agreement ID or reference code" value={loadId} onChange={event => setLoadId(event.target.value)} /><button disabled={busy === "load"} onClick={onLoad}>{busy === "load" ? "Loading…" : "Load"}</button></div>}</div></section>; }
function GoodsScreen({ draft, update, onNext }: { draft: Draft; update: <K extends keyof Draft>(key: K, value: Draft[K]) => void; onNext: () => void }) { return <Frame step="STEP 02 / GOODS" title="What is being traded?" sub="Describe the commercial goods clearly. This record stays off-chain and travels with the agreement." next={onNext} disabled={!draft.description.trim()}><label className="form-label">Category <span>optional</span><div className="choice-grid category-grid">{categories.map(category => <button type="button" className={draft.category === category ? "selected" : ""} key={category} onClick={() => update("category", category)}>{category}</button>)}</div></label><label className="form-label">Description <span>required</span><textarea autoFocus placeholder="Describe what is being traded, including model, specification, or grade if relevant" value={draft.description} onChange={event => update("description", event.target.value)} /></label><div className="two-fields"><label className="form-label">Quantity <span>optional</span><input type="number" min="0" value={draft.quantity} onChange={event => update("quantity", event.target.value)} /></label><label className="form-label">Unit <span>optional</span><select value={draft.quantityUnit} onChange={event => update("quantityUnit", event.target.value)}>{["units", "kg", "tonnes", "MT", "containers", "litres", "cubic metres", "other"].map(unit => <option key={unit}>{unit}</option>)}</select></label></div><label className="form-label">Quality standard <span>optional</span><textarea placeholder="e.g. ISO 9001, SGS pre-shipment inspection, buyer specification document" value={draft.qualityStandard} onChange={event => update("qualityStandard", event.target.value)} /></label></Frame>; }
function TransportScreen({ draft, update, onNext, onBack }: { draft: Draft; update: <K extends keyof Draft>(key: K, value: Draft[K]) => void; onNext: () => void; onBack: () => void }) { return <Frame step="STEP 03 / ROUTE" title="Where will the goods travel?" sub="The transport mode determines which delivery terms can be selected next." onBack={onBack} next={onNext}><div className="mode-grid">{modes.map(mode => <button type="button" className={draft.mode === mode.value ? "selected" : ""} key={mode.value} onClick={() => update("mode", mode.value)}><b>{mode.icon}</b><span>{mode.label}</span></button>)}</div><div className="two-fields"><label className="form-label">Origin country <span>required</span><input value={draft.originCountry} onChange={event => update("originCountry", event.target.value)} placeholder="Country" /></label><label className="form-label">Origin port or city <span>required</span><input value={draft.originPortCity} onChange={event => update("originPortCity", event.target.value)} placeholder="Port or city" /></label><label className="form-label">Destination country <span>required</span><input value={draft.destinationCountry} onChange={event => update("destinationCountry", event.target.value)} placeholder="Country" /></label><label className="form-label">Destination port or city <span>required</span><input value={draft.destinationPortCity} onChange={event => update("destinationPortCity", event.target.value)} placeholder="Port or city" /></label></div><fieldset><legend>Who arranges main freight?</legend><Radio value="seller" label="Seller arranges and pays" current={draft.freightArranger} onChange={value => update("freightArranger", value)} /><Radio value="buyer" label="Buyer arranges and pays" current={draft.freightArranger} onChange={value => update("freightArranger", value)} /><Radio value="tba" label="To be agreed" current={draft.freightArranger} onChange={value => update("freightArranger", value)} /></fieldset><fieldset><legend>Insurance arrangement</legend><Radio value="seller" label="Included in seller's price" current={draft.insuranceArranger} onChange={value => update("insuranceArranger", value)} /><Radio value="buyer" label="Buyer arranges separately" current={draft.insuranceArranger} onChange={value => update("insuranceArranger", value)} /><Radio value="tba" label="To be agreed" current={draft.insuranceArranger} onChange={value => update("insuranceArranger", value)} /></fieldset>{consistencyWarning(draft.incoterm, draft.freightArranger, draft.insuranceArranger) && <p className="consequence-warning">{consistencyWarning(draft.incoterm, draft.freightArranger, draft.insuranceArranger)}</p>}</Frame>; }; function consistencyWarning(term: string, freight: string, insurance: string) { if (["CIF", "CIP"].includes(term) && insurance === "buyer") return "Under these delivery terms, the seller provides insurance. Change the delivery terms or set insurance arrangement to seller."; if (["CFR", "CPT"].includes(term) && freight === "buyer") return "Under these delivery terms, the seller arranges main freight."; if (["CFR", "CPT"].includes(term) && insurance === "seller") return "Under these delivery terms, the buyer arranges insurance."; if (term === "EXW" && freight === "seller") return "Under EXW delivery terms, the buyer arranges main freight."; if (term === "EXW" && insurance === "seller") return "Under EXW delivery terms, the buyer arranges insurance."; if (["FOB", "FAS", "FCA"].includes(term) && freight === "seller") return "Under these delivery terms, the buyer arranges main freight."; return ""; }
function Radio({ value, label, current, onChange }: { value: string; label: string; current: string; onChange: (value: string) => void }) { return <label className="radio-row"><input type="radio" checked={current === value} onChange={() => onChange(value)} />{label}</label>; }
function TermsScreen({ mode, selected, namedPlace, onSelect, onNamedPlace, terms, onNext, onBack }: { mode: TransportMode; selected: string; namedPlace: string; onSelect: (value: string) => void; onNamedPlace: (value: string) => void; terms: readonly typeof DELIVERY_TERMS[number][]; onNext: () => void; onBack: () => void }) { const selectedTerm = terms.find(term => term.code === selected); const placeLabel = selectedTerm?.namedPlaceLabel || "Named place"; const grouped = [["origin", "Seller's responsibility ends at origin"], ["freight", "Seller pays main freight"], ["destination", "Seller delivers to destination"]] as const; return <Frame step="STEP 04 / DELIVERY TERMS" title="How are delivery responsibilities divided?" sub="Select the terms you have agreed with your counterparty." onBack={onBack} next={onNext}><div className="term-list">{grouped.map(([group, label]) => <div key={group}><h2>{label}</h2>{terms.filter(term => term.group === group).map(term => <TermCard key={term.code} term={term} selected={selected === term.code} onSelect={() => onSelect(term.code)} />)}</div>)}<label className={`term-card other-term ${selected === "OTHER" ? "selected" : ""}`}><input type="radio" name="delivery-term" checked={selected === "OTHER"} onChange={() => onSelect("OTHER")} /><div><strong>Other / not yet agreed</strong><p>Keep the delivery responsibilities open while the parties negotiate them.</p></div></label>{selected && selected !== "OTHER" && <label className="form-label named-place-field">{placeLabel} <span>required</span><input value={namedPlace} onChange={event => onNamedPlace(event.target.value)} placeholder="Specific city or port name" /></label>}</div></Frame>; }
function TermCard({ term, selected, onSelect }: { term: typeof DELIVERY_TERMS[number]; selected: boolean; onSelect: () => void }) { return <label className={`term-card ${selected ? "selected" : ""}`}><input type="radio" name="delivery-term" checked={selected} onChange={onSelect} /><div className="term-card-main"><strong>{term.code} — {term.name}</strong>{term.mostCommon && <em>most common</em>}<p>{term.description}</p><div className="risk-diagram"><span>Seller</span><i /><span>Buyer</span></div></div></label>; }
function FinancialScreen({ draft, update, onNext, onBack }: { draft: Draft; update: <K extends keyof Draft>(key: K, value: Draft[K]) => void; onNext: () => void; onBack: () => void }) { return <Frame step="STEP 05 / FINANCIAL TERMS" title="Agree the financial terms" sub="The secured amount is required before an agreement can be created." onBack={onBack} next={onNext}><label className="form-label money-field">Total secured amount <span>required · USDC</span><input type="number" min="0.000001" step="0.01" placeholder="0.00" value={draft.totalUSDC} onChange={event => update("totalUSDC", event.target.value)} /></label><label className="form-label">All milestones must be completed by <span>required</span><input type="datetime-local" min={futureDate(0)} value={draft.deliveryDeadline} onChange={event => update("deliveryDeadline", event.target.value)} /></label><label className="form-label">Both parties must agree terms by <span>required</span><input type="datetime-local" min={futureDate(0)} value={draft.negotiationExpiry} onChange={event => update("negotiationExpiry", event.target.value)} /></label><div className="two-fields"><Duration label="After terms are agreed, buyer has this long to secure the funds" value={draft.commitmentWindowSec} onChange={value => update("commitmentWindowSec", value)} /><Duration label="If a dispute is raised, the Resolution Router's assigned resolver has this long to resolve it before either party can reclaim" value={draft.arbitrationTimeoutSec} onChange={value => update("arbitrationTimeoutSec", value)} /></div></Frame>; }
function Duration({ label, value, onChange }: { label: string; value: string; onChange: (value: string) => void }) { return <label className="form-label">{label}<select value={value} onChange={event => onChange(event.target.value)}><option value="86400">1 day</option><option value="172800">2 days</option><option value="259200">3 days</option><option value="432000">5 days</option><option value="604800">7 days</option></select></label>; }
function PartiesScreen({ draft, update, session, onNext, onBack }: { draft: Draft; update: <K extends keyof Draft>(key: K, value: Draft[K]) => void; session: EmbeddedWalletSession; onNext: () => void; onBack: () => void }) { const [query, setQuery] = useState(""); const [results, setResults] = useState<CommercialProfile[]>([]); const [lookupMessage, setLookupMessage] = useState(""); useEffect(() => { if (draft.counterpartyMode !== "search" || query.trim().length < 2) { setResults([]); return; } let active = true; const timer = window.setTimeout(() => { void searchCommercialProfiles(session, query.trim()).then(value => { if (active) setResults(value); }).catch(() => { if (active) setLookupMessage("Company search is temporarily unavailable."); }); }, 300); return () => { active = false; window.clearTimeout(timer); }; }, [draft.counterpartyMode, query, session]); const changeMode = (mode: CounterpartyMode) => { update("counterpartyMode", mode); update("counterparty", ""); update("counterpartyProfile", null); setQuery(""); setResults([]); setLookupMessage(""); }; const selectProfile = (profile: CommercialProfile) => { update("counterparty", profile.walletAddress); update("counterpartyProfile", profile); setQuery(profile.companyName); setResults([]); }; const checkAddress = async () => { if (!/^0x[0-9a-fA-F]{40}$/.test(draft.counterparty)) return; setLookupMessage("Checking profile…"); try { const profile = await lookupCommercialProfile(session, draft.counterparty); update("counterpartyProfile", profile); setLookupMessage(profile ? `${profile.companyName} · ${profile.country}` : "No Arc Trade profile found. They can still join through the shared agreement."); } catch { setLookupMessage("Could not check this address right now."); } }; return <Frame step="STEP 06 / RESOLUTION POLICY" title="Add your counterparty and resolution policy" sub="You can find a known business, invite them to onboard, or use their wallet address directly. The escrow still uses ArcTrade's fixed Resolution Router." onBack={onBack} next={onNext}><fieldset><legend>How will you add your counterparty?</legend><Radio value="search" label="Search by company name" current={draft.counterpartyMode} onChange={value => changeMode(value as CounterpartyMode)} /><Radio value="invite" label="Send an invite link" current={draft.counterpartyMode} onChange={value => changeMode(value as CounterpartyMode)} /><Radio value="address" label="I have their account address" current={draft.counterpartyMode} onChange={value => changeMode(value as CounterpartyMode)} /></fieldset>{draft.counterpartyMode === "search" && <div className="counterparty-picker"><label className="form-label">Company name<span>minimum 2 characters</span><input placeholder="Search known counterparties" value={query} onChange={event => { setQuery(event.target.value); update("counterparty", ""); update("counterpartyProfile", null); }} /></label>{results.length > 0 && <div className="search-results">{results.map(profile => <button type="button" key={profile.walletAddress} onClick={() => selectProfile(profile)}><strong>{profile.companyName}</strong><span>{profile.country}{profile.tradeCategory ? ` · ${profile.tradeCategory}` : ""} · {profile.verifiedTradeCount} verified trades</span></button>)}</div>}{query.length >= 2 && !results.length && <p className="identity-note">No profile found yet. You can send an invite instead. <button className="text-button" type="button" onClick={() => changeMode("invite")}>Use invite link</button></p>}{draft.counterpartyProfile && <p className="identity-note">Selected: {draft.counterpartyProfile.companyName} · {draft.counterpartyProfile.country}</p>}</div>}{draft.counterpartyMode === "invite" && <div className="identity-note"><strong>Invite link</strong><br />We’ll create the draft first, then generate a secure seven-day link you can send to your counterparty. Their wallet will be attached when they accept.</div>}{draft.counterpartyMode === "address" && <label className="form-label">Counterparty account<span>required · wallet address</span><input placeholder="0x…" value={draft.counterparty} onChange={event => { update("counterparty", event.target.value); update("counterpartyProfile", null); }} onBlur={() => void checkAddress()} />{lookupMessage && <small>{lookupMessage}</small>}</label>}<fieldset><legend>Resolution policy</legend><Radio value="ARCTRADE_DEFAULT" label="ArcTrade default resolution" current={draft.resolutionPolicy} onChange={value => update("resolutionPolicy", value as ResolutionPolicy)} /><Radio value="MUTUAL_RESOLVER" label="Mutually selected resolver" current={draft.resolutionPolicy} onChange={value => update("resolutionPolicy", value as ResolutionPolicy)} /></fieldset>{draft.resolutionPolicy === "MUTUAL_RESOLVER" ? <label className="form-label">Nominated resolver<span>optional · assigned and signed before a dispute is resolved</span><input placeholder="0x…" value={draft.resolverAddress} onChange={event => update("resolverAddress", event.target.value)} /></label> : <p className="identity-note">No resolver wallet is required now. ArcTrade's default resolver is assigned through the signed Resolution Router workflow if a dispute occurs.</p>}<label className="form-label">Resolution Router<span>fixed · on-chain arbitration authority</span><input readOnly value={import.meta.env.VITE_RESOLUTION_ROUTER_ADDRESS || "Configured by the agreement service"} /></label><label className="form-label">Platform settlement operator<span>read-only · platform constant</span><input readOnly value={operatorAddress || "Not configured"} /></label><div className="identity-note">Your wallet<br /><code>{session.address}</code></div></Frame>; }
function InviteWaitScreen({ agreement, inviteUrl, expiresAt, session, onContinue }: { agreement: CommercialAgreement; inviteUrl: string; expiresAt: string; session: EmbeddedWalletSession; onContinue: () => void }) { const [current, setCurrent] = useState(agreement); const [copied, setCopied] = useState(false); useEffect(() => { if ((current.buyerAddress && current.sellerAddress) || !agreement) return; const timer = window.setInterval(() => { void getCommercialAgreement(session, agreement.id).then(setCurrent).catch(() => {}); }, 8000); return () => window.clearInterval(timer); }, [agreement, current.buyerAddress, current.sellerAddress, session]); const joined = Boolean(current.buyerAddress && current.sellerAddress); return <Frame step="COUNTERPARTY / INVITATION" title={joined ? "Your counterparty has joined." : "Invite your counterparty"} sub={joined ? "The agreement can now move into milestone negotiation." : "Send this private link to the business you already know. It expires in seven days."}>{joined ? <><p className="identity-note">Both wallet addresses are now attached to {current.referenceCode}.</p><button onClick={onContinue}>Continue to milestone plan</button></> : <><div className="invite-link-row"><input readOnly value={inviteUrl} /><button className="secondary" onClick={() => { void navigator.clipboard.writeText(inviteUrl).then(() => setCopied(true)); }}>{copied ? "Copied" : "Copy link"}</button></div><p className="identity-note">Waiting for your counterparty to accept. The invitation expires {new Date(expiresAt).toLocaleString()}.</p></>}</Frame>; }
function ReviewScreen({ draft, role, session, onCreate, onBack, busy }: { draft: Draft; role: Role; session: EmbeddedWalletSession; onCreate: () => void; onBack: () => void; busy: string }) { const resolution = draft.resolutionPolicy === "ARCTRADE_DEFAULT" ? "ArcTrade default resolver assigned when needed" : draft.resolverAddress ? `Mutual resolver nomination · ${draft.resolverAddress}` : "Mutual resolver selected at dispute time"; return <Frame step="STEP 07 / REVIEW" title="Review before creating" sub="The agreement is created off-chain first. No contract is deployed here." onBack={onBack} next={onCreate} nextLabel={busy === "create" ? "Creating…" : "Create agreement"} disabled={busy === "create"}><div className="review-grid"><Summary title="Your role" value={role} /><Summary title="Trade description" value={`${draft.description}${draft.quantity ? ` · ${draft.quantity} ${draft.quantityUnit}` : ""}`} /><Summary title="Transport" value={`${draft.mode} · ${draft.originPortCity}, ${draft.originCountry} → ${draft.destinationPortCity}, ${draft.destinationCountry}`} /><Summary title="Delivery terms" value={`${draft.incoterm === "OTHER" ? "Other / not yet agreed" : draft.incoterm}${draft.deliveryNamedPlace ? ` · ${draft.deliveryNamedPlace}` : ""}`} /><Summary title="Financial terms" value={`$${Number(draft.totalUSDC).toLocaleString()} USDC · delivery by ${new Date(draft.deliveryDeadline).toLocaleString()}`} /><Summary title="Resolution" value={resolution} /><Summary title="Counterparties" value={`Buyer ${role === "BUYER" ? session.address : draft.counterparty || "Pending invitation"} · Seller ${role === "SELLER" ? session.address : draft.counterparty || "Pending invitation"}`} /></div><div className="next-steps"><h2>What happens next</h2><ol><li>One party sends a milestone payment proposal.</li><li>The other party reviews only the changes and can counter-propose.</li><li>Both parties approve the same milestone array.</li><li>The buyer secures funds before the router-backed settlement contract is deployed once.</li></ol></div></Frame>; }
function Summary({ title, value }: { title: string; value: string }) { return <div className="summary-row"><span>{title}</span><strong>{value}</strong></div>; }

function BuilderScreen({ total, milestones, setMilestones, editing, setEditing, note, setNote, diff, canSend, onSave, onSend, busy, counter = false }: { total: string; milestones: MilestoneDraft[]; setMilestones: React.Dispatch<React.SetStateAction<MilestoneDraft[]>>; editing: number | null; setEditing: (value: number | null) => void; note: string; setNote: (value: string) => void; diff?: CommercialDiff | null; canSend: boolean; onSave: () => void; onSend: () => void; busy: string; counter?: boolean }) { const update = (index: number, change: Partial<MilestoneDraft>) => setMilestones(current => current.map((item, itemIndex) => itemIndex === index ? { ...item, ...change } : item)); const add = () => setMilestones(current => [...current, { description: "", basisPoints: 0, sellerDeadlineSec: 86400, buyerResponseWindowSec: 172800, disputeWindowSec: 172800, proofDescription: "", reference: current.length ? `M${current.length - 1}` : "agreement" }]); const remove = (index: number) => setMilestones(current => current.filter((_, itemIndex) => itemIndex !== index)); const editingMilestone = editing === null ? null : milestones[editing]; return <section className="commercial-frame builder-frame"><div className="commercial-step">STEP 08 / {counter ? "COUNTER-PROPOSAL" : "OPENING PROPOSAL"}</div><h1>{counter ? "Suggest different terms." : "Build the milestone payment plan."}</h1><p className="commercial-sub">Every field is editable. Dollar amounts are the primary view; payment shares are shown beside them.</p>{counter && diff && <p className="change-summary">Changed fields are marked amber. The previous proposal is shown in the negotiation diff before you send.</p>}<div className={`allocation ${canSend ? "complete" : totalBasis(milestones) > 10000 ? "over" : "under"}`}><div><strong>{amount(total, totalBasis(milestones))}</strong><span>allocated of ${Number(total || 0).toLocaleString()} USDC</span></div><b>{(totalBasis(milestones) / 100).toFixed(2)}%</b></div><p className="suggestion-disclaimer">These are suggested payment stages based on your delivery terms. They are not requirements of the delivery rule. Adjust them to match what you and your counterparty have agreed.</p><div className="builder-list">{milestones.map((milestone, index) => <article className="builder-card" key={`${index}-${milestone.description}`}><div className="builder-card-head"><span>M{index}</span><strong>{moneyFromBasis(total, milestone.basisPoints)} <small>{(milestone.basisPoints / 100).toFixed(2)}%</small></strong></div><label className="form-label">Description<input value={milestone.description} onChange={event => update(index, { description: event.target.value })} /></label><div className="inline-money"><label className="form-label">Payment share (%)<input type="number" min="0" step="0.01" value={milestone.basisPoints / 100} onChange={event => update(index, { basisPoints: Math.round(Number(event.target.value || 0) * 100) })} /></label><p>{moneyFromBasis(total, milestone.basisPoints)} USDC</p></div><p className="reference">{index === 0 ? "Seller deadline after agreement starts" : `Seller deadline after ${milestone.reference}`}</p><div className="two-fields"><label className="form-label">Seller deadline (seconds)<input type="number" min="1" value={milestone.sellerDeadlineSec} onChange={event => update(index, { sellerDeadlineSec: Number(event.target.value) })} /></label><label className="form-label">Buyer review window (hours)<input type="number" min="1" value={milestone.buyerResponseWindowSec / 3600} onChange={event => update(index, { buyerResponseWindowSec: Number(event.target.value) * 3600 })} /></label></div><label className="form-label">Proof description <span>counterparty reference</span><textarea value={milestone.proofDescription} onChange={event => update(index, { proofDescription: event.target.value })} /></label><div className="builder-card-actions"><button className="text-button" onClick={() => setEditing(index)}>Edit</button><button className="text-button danger-text" onClick={() => remove(index)} disabled={milestones.length === 1}>Remove</button></div></article>)}</div><button className="add-milestone" onClick={add}>＋ Add milestone</button>{counter && <label className="form-label note-field">Add a note to your counterparty <span>optional</span><textarea placeholder="Explain what changed and why" value={note} onChange={event => setNote(event.target.value)} /></label>}<div className="commercial-actions builder-actions"><button className="text-button" onClick={onSave}>Save draft</button><button onClick={onSend} disabled={!canSend || !!busy}>{busy === "send" ? "Sending…" : "Send proposal"}</button></div>{editingMilestone && <MilestoneModal total={total} index={editing!} milestone={editingMilestone} onChange={change => update(editing!, change)} onClose={() => setEditing(null)} />}</section>; }
function totalBasis(milestones: MilestoneDraft[]) { return milestones.reduce((sum, item) => sum + item.basisPoints, 0); }
function MilestoneModal({ total, index, milestone, onChange, onClose }: { total: string; index: number; milestone: MilestoneDraft; onChange: (change: Partial<MilestoneDraft>) => void; onClose: () => void }) { const release = moneyFromBasis(total, milestone.basisPoints); return <div className="modal-backdrop"><section className="milestone-modal"><div className="modal-head"><span>M{index}</span><button className="text-button" onClick={onClose}>Close ×</button></div><h2>Edit milestone</h2><label className="form-label">Description<input value={milestone.description} onChange={event => onChange({ description: event.target.value })} /></label><div className="inline-money"><label className="form-label">Payment share (%)<input type="number" min="0" step="0.01" value={milestone.basisPoints / 100} onChange={event => onChange({ basisPoints: Math.round(Number(event.target.value || 0) * 100) })} /></label><p>{release} USDC</p></div><label className="form-label">Seller deadline (hours)<input type="number" min="1" value={Math.round(milestone.sellerDeadlineSec / 3600)} onChange={event => onChange({ sellerDeadlineSec: Number(event.target.value) * 3600 })} /></label><label className="form-label">Reference point<select value={milestone.reference} onChange={event => onChange({ reference: event.target.value })}><option value="agreement">Agreement start</option>{Array.from({ length: index }, (_, itemIndex) => <option key={itemIndex} value={`M${itemIndex}`}>M{itemIndex}</option>)}</select></label><label className="form-label">Buyer review window (hours)<input type="number" min="1" value={milestone.buyerResponseWindowSec / 3600} onChange={event => onChange({ buyerResponseWindowSec: Number(event.target.value) * 3600 })} /></label><p className="consequence-warning">If you do not respond within {milestone.buyerResponseWindowSec / 3600} hours after your seller submits proof, payment of {release} releases automatically.</p><label className="form-label">Dispute window (hours)<input type="number" min="1" value={milestone.disputeWindowSec / 3600} onChange={event => onChange({ disputeWindowSec: Number(event.target.value) * 3600 })} /></label><p className="consequence-warning">You have {milestone.disputeWindowSec / 3600} hours after confirming to raise a dispute. After this, {release} releases with no further recourse.</p><label className="form-label">Proof document description<textarea value={milestone.proofDescription} onChange={event => onChange({ proofDescription: event.target.value })} /></label><button onClick={onClose}>Done editing</button></section></div>; }

function ProposalScreen({ agreement, proposal, role, onAccept, onChanges, busy }: { agreement: CommercialAgreement; proposal: CommercialProposal; role: Role; onAccept: () => void; onChanges: () => void; busy: string }) { return <Frame step="STEP 09 / REVIEW PROPOSAL" title="Review the milestone terms" sub={`Agreement expires ${new Date(agreement.negotiationExpiry).toLocaleString()}`}><div className="trade-strip"><strong>{agreement.goodsDescription}</strong><span>${Number(agreement.totalUSDC).toLocaleString()} USDC · {agreement.originPortCity} → {agreement.destinationPortCity} · {agreement.incoterm || "delivery terms open"}</span></div><p className="suggestion-disclaimer">These are suggested payment stages based on your delivery terms. They are not requirements of the delivery rule. Adjust them to match what you and your counterparty have agreed.</p><div className="read-only-milestones">{proposal.milestones.map((milestone, index) => <article key={index}><span>M{index}</span><div><strong>{milestone.description}</strong><small>{milestone.sellerDeadlineSec / 86400 >= 1 ? `${milestone.sellerDeadlineSec / 86400} days` : `${milestone.sellerDeadlineSec / 3600} hours`} to submit · {milestone.buyerResponseWindowSec / 3600} hours to review</small></div><b>{amount(agreement.totalUSDC, milestone.basisPoints)}<small>{(milestone.basisPoints / 100).toFixed(2)}%</small></b></article>)}</div><section className="perspective-box"><h2>{role === "SELLER" ? "What you receive from this agreement" : "Your payment schedule"}</h2>{proposal.milestones.map((milestone, index) => <p key={index}>→ {amount(agreement.totalUSDC, milestone.basisPoints)} when {milestone.description.toLowerCase()} is submitted and the review window passes without action.</p>)}</section><div className="commercial-actions"><button onClick={onAccept} disabled={busy === "accept" || proposal.proposedBy.toLowerCase() === agreementStatusAddress(agreement, role)}>{busy === "accept" ? "Recording…" : "Accept these terms"}</button><button className="outline-button" onClick={onChanges} disabled={busy === "diff"}>Suggest changes</button></div></Frame>; }
function agreementStatusAddress(agreement: CommercialAgreement, role: Role) { return String(role === "BUYER" ? agreement.buyerAddress || "" : agreement.sellerAddress || "").toLowerCase(); }
function DiffScreen({ total, diff, onAccept, onCounter, onReject, busy }: { total: string; diff: CommercialDiff; onAccept: () => void; onCounter: () => void; onReject: () => void; busy: string }) { return <Frame step="STEP 10 / CHANGES" title={`Your counterparty suggested ${diff.changedMilestones.length} changes`} sub="Only changed fields are shown. Review the consequence before deciding."><div className="diff-list">{diff.changedMilestones.map(row => <article key={row.index}><h2>M{row.index} · {row.description}</h2>{row.changes.map(change => <div className="diff-row" key={change.field}><span>{fieldName[change.field] || change.field}</span><p>Was: <del>{formatChange(change.field, change.was, total)}</del><br />Now: <strong>{formatChange(change.field, change.now, total)}</strong></p></div>)}{row.warnings.map(warning => <p className="consequence-warning" key={warning}>⚠ {warning}</p>)}</article>)}</div>{diff.note && <div className="counter-note"><span>Counterparty note</span><p>{diff.note}</p></div>}<div className="commercial-actions"><button onClick={onAccept} disabled={busy === "accept"}>{busy === "accept" ? "Recording…" : "Accept these changes"}</button><button className="outline-button" onClick={onCounter}>Propose different terms</button><button className="text-button danger-text" onClick={onReject}>Reject — revert to my last proposal</button></div></Frame>; }
function formatChange(field: string, value: unknown, total: string) { if (value === null || value === undefined) return "—"; if (field === "basisPoints") return `${moneyFromBasis(total, Number(value))} (${(Number(value) / 100).toFixed(2)}%)`; if (field.endsWith("Sec")) return `${Number(value) / (field === "sellerDeadlineSec" ? 86400 : 3600)} ${field === "sellerDeadlineSec" ? "days" : "hours"}`; return String(value); }
function MutualScreen({ agreement, milestones, role, onDeploy, busy }: { agreement: CommercialAgreement; milestones: MilestoneDraft[]; role: Role; onDeploy: () => void; busy: string }) { const deployed = agreement.status === "deployed" || Boolean(agreement.contractAddress); return <Frame step="STEP 11 / MUTUAL AGREEMENT" title="Both parties have agreed the terms." sub={deployed ? "The commercial record is now linked to the deployed settlement contract." : role === "BUYER" ? "Your next step is to secure the funds." : "Waiting for the buyer to secure the funds."}><div className="immutable-warning"><strong>The contract is deployed once.</strong><p>Before deployment, verify the buyer, seller, and secured amount. Those values cannot change after the settlement contract is created.</p></div><p className="finalization-reference">{agreement.finalized_hash ? `Agreement reference: ${agreement.finalized_hash.slice(0, 12)}` : "Terms not yet finalised"}</p><div className="read-only-milestones">{milestones.map((milestone, index) => <article key={index}><span>M{index}</span><div><strong>{milestone.description}</strong><small>{milestone.buyerResponseWindowSec / 3600} hour review window</small></div><b>{amount(agreement.totalUSDC, milestone.basisPoints)}<small>{(milestone.basisPoints / 100).toFixed(2)}%</small></b></article>)}</div>{deployed ? <div className="deployed-state"><strong>Deployed at {agreement.contractAddress}</strong><p>Existing settlement operations can continue from the live agreement dashboard.</p></div> : role === "BUYER" ? <><p className="countdown-copy">Buyer commitment window: {agreement.commitmentWindowSec / 86400} days after agreement.</p><button onClick={onDeploy} disabled={busy === "deploy"}>{busy === "deploy" ? "Deploying and proposing milestones…" : "Secure the funds →"}</button></> : <p className="waiting-copy">Buyer must secure funds within {agreement.commitmentWindowSec / 86400} days. The settlement contract has not been deployed.</p>}</Frame>; }
